export const eras=[{id:'all',label:'すべて',range:'全時代'},{id:'ancient',label:'古代',range:'〜499年生まれ'},{id:'medieval',label:'中世',range:'500〜1499年生まれ'},{id:'early',label:'近世',range:'1500〜1799年生まれ'},{id:'nineteenth',label:'19世紀',range:'1800〜1899年生まれ'},{id:'twentieth',label:'20世紀',range:'1900年以降生まれ'}];
export function eraOf(p){return p.born<500?'ancient':p.born<1500?'medieval':p.born<1800?'early':p.born<1900?'nineteenth':'twentieth'}
